		$(document).ready(function () {
			try {
				$(".widgetSearchButton.widgetSearchButton6d0aad96-a9db-488f-a487-ef19c3a7cdb4").click(function (e) {
				e.preventDefault();
					if (false||$("#ysnSearchOnlyDept6d0aad96-a9db-488f-a487-ef19c3a7cdb4").is(':checked'))
					{
						doWidgetSearch($(this).siblings(".widgetSearchBox").val(), Number(0));
					}
					else {
						doWidgetSearch($(this).siblings(".widgetSearchBox").val(), 0);
					}
			});
			$("#searchField6d0aad96-a9db-488f-a487-ef19c3a7cdb4").keypress(function (e) {
				if (window.clipboardData) {
					if (e.keyCode === 13) {
						if ($("#ysnSearchOnlyDept6d0aad96-a9db-488f-a487-ef19c3a7cdb4").is(':checked') || false) {
								doWidgetSearch($(this).val(), Number(0));
							} else {
								doWidgetSearch($(this).val(), 0);
							}
						return false;
					}
				} else {
					if (e.which === 13) {
						if ($("#ysnSearchOnlyDept6d0aad96-a9db-488f-a487-ef19c3a7cdb4").is(':checked') || false) {
								doWidgetSearch($(this).val(), Number(0));
							} else {
								doWidgetSearch($(this).val(), 0);
							}
						return false;
					}
				}
				return true;
			});

				if (true) {
					var currentRequest = null;
					var $searchField = $("#searchField6d0aad96-a9db-488f-a487-ef19c3a7cdb4").autocomplete({
						source: function (request, response) {
							currentRequest = $.ajax({
								url: '/Search/AutoComplete' + ($("#ysnSearchOnlyDept6d0aad96-a9db-488f-a487-ef19c3a7cdb4").is(':checked') || false? '?departmentId=0' : ''),
								dataType: "json",
								timeout: 10000,
								beforeSend: function () {
									if (currentRequest != null) {
										currentRequest.abort();
									}
								},
								data:
								{
									term: request.term,
								},
								success: function (data) {
									response(data);
									$('.autoCompleteError').remove();
								},
								error: function (xmlhttprequest, textstatus, message) {
									if (textstatus === "timeout") {
										if ($("#searchField6d0aad96-a9db-488f-a487-ef19c3a7cdb4").siblings('.autoCompleteError').length == 0)
											$('
Search autocomplete is currently not responding. Please try again later.').insertAfter($("#searchField6d0aad96-a9db-488f-a487-ef19c3a7cdb4"));
									}
								}
							});
						},
						html: true,
						delay: 500,
						select: function (event, ui) {
							$(this).val(ui.item.value);
							$(this).next().click();
						}
					});

					$searchField.data("ui-autocomplete")._renderItem = function (ul, item) {
						return $("
")
							.data("ui-autocomplete-item", item)
							.append("" + item.label + "")
							.appendTo(ul);
					};
}
}
			catch(e) {} //we're going to eat this error. Autocomplete won't work but we dont wan't to break anything else on the page.
		});

